#include <iostream>
#include <cstdarg>

// A variadic function to find the sum of 'n' integers
int sum(int count, ...) {
    va_list args;
    va_start(args, count); // Initialize args with the number of fixed parameters

    int total = 0;
    for (int i = 0; i < count; i++) {
        total += va_arg(args, int); // Fetch next argument as int
    }

    va_end(args); // Clean up the va_list
    return total;
}

int main() {
    std::cout << "Sum of 3 numbers (10, 20, 30): " << sum(3, 10, 20, 30) << std::endl;
    std::cout << "Sum of 5 numbers (1, 2, 3, 4, 5): " << sum(5, 1, 2, 3, 4, 5) << std::endl;
    return 0;
}

