    bitset<N> bs;                    // all bits 0
    bs.set(2);                       // 0000000100
    bs.set(5);                       // 0000100100
    bs.flip(2);                      // toggle bit 2 -> 0000100000
    cout << "Bitset: " << bs << '\n'; // prints 0000100000
    cout << "Count of 1s: " << bs.count() << '\n'; // 1
    // bulk operation example
    bitset<N> mask(string("1111100000")); // bits 5-9 = 1
    bitset<N> result = bs | mask;   // union
    cout << "Result: " << result << '\n'; // 1111100000
    return 0;
}

