#include <iostream>
#include <vector>
#include <algorithm>

struct Student {
    std::string name;
    int marks;
};

int main() {
    std::vector<Student> students = {{"Alice", 85}, {"Bob", 92}, {"Charlie", 85}};

    // Custom sort: Descending by marks, then ascending by name if marks are equal
    std::sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
        if (a.marks != b.marks)
            return a.marks > b.marks; // Higher marks first
        return a.name < b.name;       // Alphabetical order if marks match
    });

    for (const auto& s : students) {
        std::cout << s.name << ": " << s.marks << "\n";
    }
    return 0;
}

